                isinstance(fseq, int)
                and not isinstance(fseq, bool)
                and 1 <= fseq <= total_audit
            )
            first_event = chain[fseq - 1] if fseq_ok else None
            if (
                not fseq_ok
                or first_event is None
                or first_event[6] != 0
                or first_event[2] != ckey
            ):
