def _timeout_fire(self, now_ms):
    """超时演练触发：在普通老化与晋升前原子清场，O(S log A + Q)。

    挂起全部在线会话、期限清零并释放租约（静态址仅退租）；按入队序将
    全部队项记超时（capacity 事件沿用既有规则记其 sid 与入队序）后删除；
    最后清除待触发。本批不晋升、不半释放。返回按入队序的超时入队序列表
    （供推进输出“变更”）。
    """
