        if session["state"] == _STATE_ONLINE:
            self._release(session)
            session["state"] = _STATE_SUSPENDED
            session["deadline"] = 0
    timed_out = [
        (queued_sid, self._capacity_queue[queued_sid][4])
        for queued_sid in self._queue_order
    ]
