    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

def _forecast_address(self, pool, user, now_ms, lease_ips):
    """只读判定 default 池此刻能否为 user 取址（不弹堆、不登租）。

    lease_ips 为本次预测中已占用的动态址集合（含真实持租与预测中已晋升
    项）。返回原因串：可分配返回 ""；池处于耗尽演练返回“池故障”；缺
    default 池返回“无池”；静态址已被占或动态堆无空闲返回“地址”。
    """
    if pool is None:
        return "无池"
    if self._pool_is_exhausted(_DEFAULT_POOL_ID, now_ms):
        return "池故障"
    ip_int = pool.static.get(user)
    if ip_int is None:
        for candidate_ip in pool.free:
            if (
                candidate_ip not in pool.leases
                and candidate_ip not in lease_ips
            ):
                return ""
        return "地址"
    if ip_int in pool.leases or ip_int in lease_ips:
        # 静态地址专属该用户，同一时刻只能租给一个会话。
        return "地址"
    return ""

def capacity_forecast(self, now_ms, limit=100):
    """只读预测此刻一次“推进”的结果，返回 LF 结尾紧凑 JSON，不改任何状态。

    now_ms/limit 须为非 bool 的 int：类型不符 TypeError；now_ms < 0 或
    limit ∉ [1,1000] 抛 ValueError。不老化、不入缓存、不记审计/capacity
    事件、不写任何状态（会话、队列、地址租约、触发均保持原样）。

    预测口径与 capacity“推进”一致：在线期限或租期 <= now_ms 即释址，
    期限到期（含同刻）另转挂起（挂起不持址、不计在线但仍占全局/用户/模板
    上限）；待触发且 now_ms>=触发值的全局超时演练到点时，不老化、不晋升，
    全队项按入队序记超时。否则队项截止 <= now_ms 为超时，其余依入队序按
    全局、单用户、模板上限及 default 池取址规则模拟晋升，前项占址/占额
    影响后项判定。等待原因按 全局/用户/模板/无池/池故障/地址 的优先级
    取首个不满足项。

    顶层键序“时刻/剩余/项目”，均为 int/int/list；项目取入队序前 limit
    项，剩余为未列项数。项键序“会话/用户/入队序/结果/原因”，前两项为
    str、入队序为 int；结果仅“晋升/超时/等待”，原因分别为空串/“截止”/
    上述六值之一。时间 O(S+limit)，辅助空间 O(U+T+limit)（S 为会话数、
    U 为用户数、T 为模板数）。
    """
    _check_int("now_ms", now_ms, 0)
    _check_int("limit", limit, 1)
    if limit > 1000:
        raise ValueError(f"limit must be <= 1000, got {limit}")

    total_count = 0
    per_user = {}
    per_template = {}
    lease_ips = set()
    drill_armed = self._timeout_at is not None and now_ms >= self._timeout_at

    pool = self._pools.get(_DEFAULT_POOL_ID)
    # 会话表单扫：非下线计数（挂起占全局/用户/模板上限），持租址入占用集。
    # 到点超时演练时真实会话不老化（推进路径直接挂起在线会话），故不据此
    # 释放任何真实持址。
    if not drill_armed:
        for session in self._sessions.values():
            state = session["state"]
            if state == _STATE_OFFLINE:
                continue
            expired = state == _STATE_ONLINE and session["deadline"] <= now_ms
            lease_due = (
                state == _STATE_ONLINE and session["lease"] <= now_ms
            )
            frees_addr = state == _STATE_ONLINE and (expired or lease_due)
            if not frees_addr and session["ip"] is not None:
                lease_ips.add(session["ip"])
            if expired:
                # 期限到期转挂起：不持址、不计在线，但仍占各类上限。
                continue
            # 在线（含租期到但未挂起、仍占上限）与未到期挂起计入计数。
            total_count += 1
            user = session["user"]
            per_user[user] = per_user.get(user, 0) + 1
            template_id = self._user_templates.get(user)
            if template_id is not None:
                per_template[template_id] = (
                    per_template.get(template_id, 0) + 1
                )

    items = []
    queued_total = len(self._queue_order)
    take = min(limit, queued_total)
    for index in range(queued_total):
        queued_sid = self._queue_order[index]
        entry = self._capacity_queue[queued_sid]
        user = entry[0]
        order = entry[4]
        if index < take:
            items.append(
                {"会话": queued_sid, "用户": user, "入队序": order}
            )
        if drill_armed:
            # 到点演练：全部队项超时，不晋升。
            if index < take:
                items[index]["结果"] = _CAP_TIMEOUT
                items[index]["原因"] = "截止"
            continue
        if entry[3] <= now_ms:
            if index < take:
                items[index]["结果"] = _CAP_TIMEOUT
                items[index]["原因"] = "截止"
            continue

        # 晋升闸按全局、用户、模板、default 池取址的固定优先级取首个不满足
        # 项作为等待原因；前项模拟晋升后占址/占额影响后项。
        reason = ""
        if total_count >= self._total:
            reason = "全局"
        elif per_user.get(user, 0) >= self._per:
            reason = "用户"
        else:
            template_id = self._user_templates.get(user)
            if template_id is not None:
                session_limit = self._templates[template_id][3]
                if (
                    session_limit
                    and per_template.get(template_id, 0) >= session_limit
                ):
                    reason = "模板"
            if reason == "":
                reason = self._forecast_address(
                    pool, user, now_ms, lease_ips
                )
        if reason == "":
            # 模拟晋升：占全局/用户/模板名额并占址，供后项判定。
            total_count += 1
            per_user[user] = per_user.get(user, 0) + 1
            template_id = self._user_templates.get(user)
            if template_id is not None:
                per_template[template_id] = (
                    per_template.get(template_id, 0) + 1
                )
            ip_int = pool.static.get(user)
            if ip_int is None:
                for candidate_ip in pool.free:
                    if (
                        candidate_ip not in pool.leases
                        and candidate_ip not in lease_ips
                    ):
                        ip_int = candidate_ip
                        break
            lease_ips.add(ip_int)
            if index < take:
                items[index]["结果"] = _CAP_PROMOTED
                items[index]["原因"] = ""
        elif index < take:
            items[index]["结果"] = "等待"
            items[index]["原因"] = reason

    payload = {
        "时刻": now_ms,
        "剩余": queued_total - take,
        "项目": items,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

