    return (copy.deepcopy(s._sessions), list(s._queue_order),
            copy.deepcopy(s._capacity_queue),
            copy.deepcopy([(list(p.free),dict(p.leases)) for p in s._pools.values()]),
            s._timeout_at, len(s._capacity_events))

def run(pool, total, per, idle, lease, now, limit, arm=None, fault_until=None, tmpl=None):
