    if pool is not None: kw["pool"]=pool
    s=Sessions(auth,total,per,idle,lease_ms=lease,**kw)
    if tmpl:
        # tmpl: {tid: limit}; bind users round-robin
        for tid,lim in tmpl.items():
            s._templates[tid]=("r","b","q",lim,"拒绝")
        for i,u in enumerate(USERS):
            s._user_templates[u]=list(tmpl)[i%len(tmpl)]
